draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 - 100, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // watermelon
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 100, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // cutting motion
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(W / 2 - 50 + 20 * Math.sin(t), H / 2 - 20 * Math.cos(t));
  ctx.lineTo(W / 2 + 50 + 20 * Math.sin(t), H / 2 + 20 * Math.cos(t));
  ctx.lineWidth = 5;
  ctx.stroke();

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 2 - 150, H / 2 + 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 150, H / 2 + 70);
  ctx.lineTo(W / 2 - 150, H / 2 + 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 150, H / 2 + 100);
  ctx.lineTo(W / 2 - 120, H / 2 + 120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 150, H / 2 + 100);
  ctx.lineTo(W / 2 - 180, H / 2 + 120);
  ctx.stroke();

  ctx.restore();
}
